      const parts = externalAnimationV1.walkParts?.[direction] || {};
      for (const part of ["start", "loop", "stop"]) {
        if (parts[part]) entries.push({ key: `external walk_${direction}_${part}${direction === "west" ? " mirrored" : ""}`, type: "walk", frame: parts[part] });
