    const { ctx } = this;
    ctx.fillStyle = "rgba(255,255,255,0.06)";
    ctx.fillRect(x, y, 286, 196);
    ctx.strokeStyle = "rgba(255,255,255,0.18)";
    ctx.strokeRect(x, y, 286, 196);
    ctx.fillStyle = "#f4ead8";
    ctx.font = "700 14px Arial";
    ctx.fillText(entry.key, x + 10, y + 20);

