  UNPACKED_DIR,
  animationFolders,
  alphaBounds,
  ensureDir,
  ensureExternalAnimationDirs,
  EXTERNAL_IDLE_DEFAULT_FPS,
  EXTERNAL_WALK_DEFAULT_FPS,
