  const flipX = typeof config.flipX === "boolean" ? config.flipX : undefined;
  const flipXWest = typeof config.flipXWest === "boolean" ? config.flipXWest : undefined;
  const stableVisualBounds = config.stableVisualBounds === true;
  const metadata = {
